package cn.binbin.crm;
import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import static cn.binbin.crm.TradeService.*;import static cn.binbin.crm.P3Base.map;
@Service
public class PilotService {
 public record Record(@NotBlank @Size(max=2000) String notes){}
 private final P7Records r;private final P3Base b;private final P7Permissions p;private final ObjectStore storage;private final RecoveryService mail;private final boolean automation;
 public PilotService(P7Records r,P7Permissions p,ObjectStore storage,RecoveryService mail,@Value("${CRM_AUTOMATION_SCHEDULE_ENABLED:false}") boolean automation){this.r=r;this.b=r.b;this.p=p;this.storage=storage;this.mail=mail;this.automation=automation;}
 private void access(AuthService.Actor a){p.admin(a);if(!a.canReadCustomers()||!a.access().readAll()||!a.tradeAccess().contracts().readAll())throw ApiError.forbidden("完整试点检查需要企业管理员及全企业业务读取权限");}
 private long count(AuthService.Actor a,String sql){return b.db.queryForObject(sql,map("tenant",a.tenant().id()),Long.class);}
 private Map<String,Object> check(String code,String name,boolean pass,String detail,String view){return map("code",code,"name",name,"status",pass?"PASS":"TODO","detail",detail,"view",view);}
 private Object evaluate(AuthService.Actor a){var checks=new ArrayList<Map<String,Object>>();checks.add(check("subscription","企业订阅有效",a.tenant().subscriptionEnd().isAfter(Instant.now()),"确认试点期间企业保持启用且订阅未到期","billing"));checks.add(check("organization","部门及成员已配置",count(a,"SELECT count(*) FROM org_department WHERE tenant_id=:tenant AND active")>0&&count(a,"SELECT count(*) FROM sys_tenant_member WHERE tenant_id=:tenant AND status='ACTIVE'")>=2,"至少配置一个部门及两位独立成员","members"));checks.add(check("reviewers","独立审批与财务复核人员",count(a,"SELECT count(DISTINCT m.user_id) FROM sys_tenant_member m JOIN sys_member_role r ON r.tenant_id=m.tenant_id AND r.member_id=m.id JOIN iam_user u ON u.id=m.user_id WHERE m.tenant_id=:tenant AND m.status='ACTIVE' AND u.status='ACTIVE' AND NOT u.must_change_password AND r.role_code='SALES_MANAGER'")>=2,"报价、支出及提成复核需要独立账号，不能自审","policies"));checks.add(check("customer","客户资料已就绪",count(a,"SELECT count(*) FROM crm_customer WHERE tenant_id=:tenant AND NOT in_pool AND merged_into_customer_id IS NULL")>0,"可使用迁移模板或客户导入功能准备试点资料","migration"));for(var type:List.of("ORDER","INVOICE","COMMISSION","WEEKLY")){boolean allowed=r.allowed(a,type,false);long n=allowed?count(a,"SELECT count(*) FROM "+P7Records.TABLES.get(type)+" WHERE tenant_id=:tenant AND status "+switch(type){case "ORDER"->"IN('CONFIRMED','IN_DELIVERY','DELIVERED')";case "INVOICE"->"='ISSUED'";case "COMMISSION"->"='LOCKED'";default->"='APPROVED'";}):0;checks.add(check(type,"业务闭环："+P7Records.NAMES.get(type),n>0,allowed?"至少完成一笔真实或隔离演练业务；记录保留在原模块":"当前对象权限不足，不能完成此项核验","object-workspace"));}checks.add(check("cash","确认回款已演练",a.tradeAccess().receiptRead()&&count(a,"SELECT count(*) FROM crm_receipt WHERE tenant_id=:tenant AND status IN('CONFIRMED','REVERSED')")>0,"按到账日期核对回款、冲销和业绩口径","receipts"));checks.add(check("service","服务处理已演练",a.p3Access().tickets().read()&&count(a,"SELECT count(*) FROM crm_ticket WHERE tenant_id=:tenant AND status IN('RESOLVED','CLOSED')")>0,"受理、派工、接单、处理、评价及重新开启按服务周期核验","tickets"));checks.add(check("storage","附件服务已配置",storage.configured(),"附件还需使用获准试点账号完成实际上传和下载","attachments"));checks.add(check("mail","正式邮件参数已配置",mail.enabled(),"参数配置可在此核验；实际邮件投递需使用企业核验邮箱演练，不代表已发送邮件","members"));checks.add(check("automation","自动化调度已开启",automation,"定时规则由服务端调度执行，可在规则页查看执行记录","automation"));var backup=b.rows("SELECT finished_at,status FROM sys_job_run WHERE job_name='DATABASE_BACKUP' AND status='SUCCESS' ORDER BY finished_at DESC LIMIT 1",Map.of());boolean recent=!backup.isEmpty()&&ServiceDeskService.time(backup.getFirst(),"finishedAt").isAfter(Instant.now().minusSeconds(36*3600));checks.add(check("backup","近期加密备份成功",recent,"恢复演练证据由产品方归档；此项只核验最近36小时成功备份",""));return map("checks",checks,"passed",checks.stream().filter(c->"PASS".equals(c.get("status"))).count(),"total",checks.size(),"softwareAcceptanceSeparate",true,"externalTrialRequired",true,"instructions","由产品方与试点企业指定联系人、核对真实资料并执行验收；系统检查不替代客户实际签收。");}
 public Object readiness(AuthService.Session s){return b.tx.execute(st->{var a=b.auth.actor(s);access(a);return evaluate(a);});}
 public Object record(AuthService.Session s,Record i,UUID trace){return b.tx.execute(st->{var a=b.auth.actor(s);access(a);p.feature(a,"migration");UUID id=UUID.randomUUID();Object checks=evaluate(a);b.db.update("INSERT INTO crm_pilot_run(id,tenant_id,actor_member_id,checks,notes) VALUES(:id,:tenant,:member,cast(:checks AS jsonb),:notes)",map("id",id,"tenant",a.tenant().id(),"member",a.tenant().memberId(),"checks",b.json(checks),"notes",text(i.notes())));b.audit(a,"PILOT_CHECK_RECORDED","PILOT",id,0,trace);return map("id",id,"readiness",checks);});}
 public Object history(AuthService.Session s){return b.tx.execute(st->{var a=b.auth.actor(s);access(a);return map("items",b.rows("SELECT id,actor_member_id,notes,created_at FROM crm_pilot_run WHERE tenant_id=:tenant ORDER BY created_at DESC,id LIMIT 100",map("tenant",a.tenant().id())));});}
}
